sys_script.script:
(function executeRule(current, previous) {

    var invoiceIds = [];

    // Get current Invoice
    if (current.getValue('invoice')) {
        invoiceIds.push(current.getValue('invoice'));
    }

    // Get previous Invoice if reference changed
    if (previous && previous.getValue('invoice')) {
        var oldInvoiceId = previous.getValue('invoice');

        if (invoiceIds.indexOf(oldInvoiceId) === -1) {
            invoiceIds.push(oldInvoiceId);
        }
    }

    // Recalculate each affected Invoice
    for (var i = 0; i < invoiceIds.length; i++) {

        var total = 0;

        var charge = new GlideRecord('x_2223823_apollo_0_charge_line');
        charge.addQuery('invoice', invoiceIds[i]);
        charge.addQuery('status', 'invoiced');
        charge.query();

        while (charge.next()) {
            total += parseFloat(charge.getValue('amount')) || 0;
        }

        var invoice = new GlideRecord('x_2223823_apollo_0_invoice');

        if (invoice.get(invoiceIds[i])) {

            invoice.setValue('total_amount', total);

            var paidAmount = parseFloat(
                invoice.getValue('paid_amount')
            ) || 0;

            invoice.setValue('total_balance', total - paidAmount);

            invoice.update();
        }
    }

})(current, previous);
